import React, { useState, useEffect } from 'react';
import EmergencyInfoPage from './EmergencyInfoPage'; // Assume this is your emergency page component

// Define the URL for your local Python Flask API
// Note: This assumes your mobile device or simulator can access your local machine's IP. 
// You might need to replace '127.0.0.1' with your computer's actual local IP address (e.g., 192.168.1.10).
const API_URL = 'http://127.0.0.1:5000/api/emergency_status';
const POLLING_INTERVAL = 2000; // Check every 2 seconds

function EmergencyMonitor() {
  const [emergencyDetected, setEmergencyDetected] = useState(false);
  const [loading, setLoading] = useState(true);

  // Function to fetch the status from the Python backend
  const checkEmergencyStatus = async () => {
    try {
      const response = await fetch(API_URL);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      
      // Update state based on the backend's response
      if (data.detected === true && !emergencyDetected) {
        console.log("🚨 Emergency signal received from backend!");
        setEmergencyDetected(true);
      }

    } catch (error) {
      console.error("Failed to fetch emergency status. Is the Python server running?", error);
    } finally {
      setLoading(false);
    }
  };

  // useEffect hook to set up the polling interval
  useEffect(() => {
    // 1. Check immediately on mount
    checkEmergencyStatus();

    // 2. Set up the interval for continuous polling
    const intervalId = setInterval(checkEmergencyStatus, POLLING_INTERVAL);

    // 3. Cleanup function: clear the interval when the component unmounts
    return () => clearInterval(intervalId);
  }, [emergencyDetected]); // Dependency array: Re-run effect only if emergencyDetected changes

  // --- RENDERING ---
  if (loading) {
    return <div>Connecting to local detection service...</div>;
  }

  if (emergencyDetected) {
    // If the flag is TRUE, show the emergency page
    return <EmergencyInfoPage />;
  }

  // Otherwise, show the main monitoring UI
  return (
    <div>
      <h1>Listening for Keywords...</h1>
      <p>Local status: Monitoring (Polling API every 2 seconds)</p>
      {/* You can show debugging info here */}
    </div>
  );
}

export default EmergencyMonitor;
